'domaine-de-chevalier|rose-de-chevalier|2016':{food:'mets/vin: crabe, œufs, paella, pizza, viande blanche, carpaccio de bœuf, crevettes etc.',src:'Rose-de-Chevalier-2016-FT-FR-C0834.pdf'},
