'du-tertre|les-hauts-du-tertre|2011':{blend:{CS:60,ME:25,CF:15},months:'12',oak:30,src:'Hauts-du-Tertre-2011-FT-FR-C1145.pdf'},
'du-tertre|les-hauts-du-tertre|2013':{yld:45,months:'12-15',src:'Haut-du-Tertre-2013-FT-FR-C1145.pdf',alc:13,oak:45},
