'issan|blason-d-issan|2010':{ph:3.72,yld:42,src:'BLASON_ISSAN_2010.pdf',blend:{CS:51,ME:49},oak:35,pick:{ALL:'09-27|'}},
'issan|blason-d-issan|2011':{blend:{CS:60,ME:40},ph:3.58,yld:36,src:'BLASON_ISSAN_2011.pdf',oak:35,pick:{ALL:'09-26|'}},
'issan|blason-d-issan|2012':{blend:{CS:60,ME:40},ph:3.71,yld:37,src:'BLASON_ISSAN_2012.pdf',oak:35,pick:{ALL:'10-17|'}},
'issan|blason-d-issan|2013':{blend:{CS:43,ME:57},ph:3.64,yld:28,src:'BLASON_ISSAN_2013.pdf',oak:35,pick:{ALL:'10-12|'}},
'issan|blason-d-issan|2014':{ph:3.67,yld:44,src:'BLASON_ISSAN_2014.pdf',blend:{CS:47,ME:53},oak:35,pick:{ALL:'09-25|'}},
'issan|blason-d-issan|2015':{blend:{CS:60,ME:40},ph:3.69,yld:40,press:{'Neal Martin':'89-91'},src:'BLASON_ISSAN_2015.pdf',oak:35,pick:{ALL:'09-21|'}},
'issan|moulin-d-issan|2005':{blend:{CS:50,ME:50},ph:3.68,yld:44,src:'MOULIN_ISSAN_2005.pdf',oak:25,pick:{ALL:'09-21|'}},
'issan|moulin-d-issan|2006':{blend:{CS:50,ME:50},ph:3.72,yld:44,src:'MOULIN_ISSAN_2006.pdf',oak:25,pick:{ALL:'09-19|'}},
'issan|moulin-d-issan|2007':{blend:{CS:50,ME:50},ph:3.75,yld:44,src:'MOULIN_ISSAN_2007.pdf',oak:25,pick:{ALL:'09-24|'}},
'issan|moulin-d-issan|2008':{blend:{CS:50,ME:50},ph:3.83,yld:30,src:'MOULIN_ISSAN_2008.pdf',oak:25,pick:{ALL:'09-29|'}},
'issan|moulin-d-issan|2009':{blend:{CS:50,ME:50},ph:3.83,yld:35,src:'MOULIN_ISSAN_2009.pdf',oak:25,pick:{ALL:'09-23|'}},
'issan|moulin-d-issan|2010':{blend:{CS:10,ME:90},ph:3.64,yld:42,src:'MOULIN_ISSAN_2010.pdf',oak:25,pick:{ALL:'09-27|'}},
'issan|moulin-d-issan|2011':{blend:{CS:10,ME:90},ph:3.61,yld:36,src:'MOULIN_ISSAN_2011.pdf',oak:25,pick:{ALL:'09-26|'}},
