'smith-haut-lafitte|ch-teau-smith-haut-lafitte-blanc|2018':{oak:50,yld:28,months:'12',press:{'Decanter':'94','Falstaff':'95','James Suckling':'98','Jancis Robinson':'17','Neal Martin':'94','Vinous':'95','Wine Advocate':'96','Wine Spectator':'96','Yves Beck':'95'},src:'2018-SHL-Blanc-FR-notes-bouteilles.pdf',blend:{SB:90,SEM:5,SG:5}},
