'haut-bages-liberal|la-chapelle-de-haut-bages-liberal|2017':{blend:{CS:45,ME:55},months:'12',src:'Fiche-technique-LA-CHAPELLE-DE-HAUT-BAGES-LIBERAL-2017.pdf'},
